const items = $('Items bajo minimo sin alerta').all().map(i => i.json);
let texto = 'ALERTA DE REPOSICION - La Cantina del Cafe\n';
texto += 'Articulos en o cerca del stock minimo:\n\n';
for (const it of items) {
  texto += `- ${it.articulo}: stock ${Number(it.stock_actual)} ${it.unidad} (minimo ${Number(it.stock_minimo)})\n`;
}
return [{ json: { mensaje: texto, total: items.length } }];
